<template><div class="banner-manager"><section class="chapter-guide"><div><span class="eyebrow">BANNER LIBRARY</span><h2>让首页的每一帧，都传递力量</h2><p>管理首页轮播图片，点击图片可查看完整预览。</p></div><el-button type="primary" icon="el-icon-plus" @click="openUpload">添加轮播图</el-button></section><div class="banner-summary"><span>全部图片 <strong>{{ images.length }}</strong></span><span>建议比例 12:5 · 支持 JPG / PNG / GIF</span></div><div v-if="images.length" class="banner-grid"><el-card v-for="(item,index) in images" :key="item.id" class="banner-tile"><el-image :src="item.url" fit="contain" :preview-src-list="images.map(image=>image.url)"><div slot="error" class="banner-error"><i class="el-icon-picture-outline"/> 图片加载失败</div></el-image><div class="banner-tile-footer"><div><small>HOMEPAGE BANNER</small><strong>首页轮播图 {{ String(index+1).padStart(2,'0') }}</strong></div><el-button type="text" icon="el-icon-delete" @click="removeImage(item)">删除</el-button></div></el-card></div><el-empty v-else description="暂无轮播图，上传第一张图片"/><el-dialog title="添加轮播图" :visible.sync="visible" width="560px" :close-on-click-modal="false"><el-upload ref="upload" action="" drag :auto-upload="false" :limit="1" accept="image/jpeg,image/png,image/gif" :on-change="selectFile" :on-remove="clearFile" :on-exceed="()=> $message.warning('每次请选择一张图片')"><i class="el-icon-upload"/><div class="el-upload__text">拖动图片到这里，或<em>点击选择</em></div><div slot="tip" class="el-upload__tip">建议使用横向宽幅图片，单张不超过 10 MB。</div></el-upload><img v-if="preview" :src="preview" class="banner-upload-preview" alt="待上传图片预览"/><span slot="footer"><el-button :disabled="saving" @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveImage">确认添加</el-button></span></el-dialog></div></template>
<script>
import {getAllSwiper,addSwiper,deleteSwiperById} from '@/api/swiper';
export default {data:()=>({images:[],visible:false,file:null,preview:'',saving:false}),mounted(){this.load()},beforeDestroy(){this.clearFile()},methods:{async load(){try{const res=await getAllSwiper();this.images=res.data||[]}catch(e){}},openUpload(){this.clearFile();this.visible=true;this.$nextTick(()=>this.$refs.upload&&this.$refs.upload.clearFiles())},clearFile(){if(this.preview)URL.revokeObjectURL(this.preview);this.file=null;this.preview=''},selectFile(file){if(!['image/jpeg','image/png','image/gif'].includes(file.raw.type)||file.size>10*1024*1024){this.$message.warning('请选择 10 MB 以内的 JPG、PNG 或 GIF 图片');this.$refs.upload.clearFiles();this.clearFile();return}this.clearFile();this.file=file.raw;this.preview=URL.createObjectURL(this.file)},async saveImage(){if(!this.file)return this.$message.warning('请先选择图片');this.saving=true;try{const data=new FormData();data.append('file',this.file);await addSwiper(data);this.$message.success('轮播图添加成功');this.visible=false;this.clearFile();await this.load()}catch(e){}finally{this.saving=false}},async removeImage(item){try{await this.$confirm('确认删除这张首页轮播图？删除后将不再展示。','删除轮播图',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'保留图片'})}catch(e){return}try{await deleteSwiperById({id:item.id});this.$message.success('轮播图已删除');await this.load()}catch(e){}}}};
</script>
